/**
 * usb_kill_urb - cancel a transfer request and wait for it to finish
 * @urb: pointer to URB describing a previously submitted request,
 *	may be NULL
 *
 * This routine cancels an in-progress request.  It is guaranteed that
 * upon return all completion handlers will have finished and the URB
 * will be totally idle and available for reuse.  These features make
 * this an ideal way to stop I/O in a disconnect() callback or close()
 * function.  If the request has not already finished or been unlinked
 * the completion handler will see urb->status == -ENOENT.
 *
 * While the routine is running, attempts to resubmit the URB will fail
 * with error -EPERM.  Thus even if the URB's completion handler always
 * tries to resubmit, it will not succeed and the URB will become idle.
 *
 * The URB must not be deallocated while this routine is running.  In
 * particular, when a driver calls this routine, it must insure that the
 * completion handler cannot deallocate the URB.
 *
 * This routine may not be used in an interrupt context (such as a bottom
 * half or a completion handler), or when holding a spinlock, or in other
 * situations where the caller can't schedule().
 *
 * This routine should not be called by a driver after its disconnect
 * method has returned.
 */
void usb_kill_urb(struct urb *urb)
{
	might_sleep();
	if (!(urb && urb->dev && urb->ep))
		return;
	atomic_inc(&urb->reject);
	/*
	 * Order the write of urb->reject above before the read
	 * of urb->use_count below.  Pairs with the barriers in
	 * __usb_hcd_giveback_urb() and usb_hcd_submit_urb().
	 */
	smp_mb__after_atomic();

	usb_hcd_unlink_urb(urb, -ENOENT);
	wait_event(usb_kill_urb_queue, atomic_read(&urb->use_count) == 0);

	atomic_dec(&urb->reject);
}
EXPORT_SYMBOL_GPL(usb_kill_urb);

/**
 * usb_poison_urb - reliably kill a transfer and prevent further use of an URB
 * @urb: pointer to URB describing a previously submitted request,
 *	may be NULL
 *
 * This routine cancels an in-progress request.  It is guaranteed that
 * upon return all completion handlers will have finished and the URB
 * will be totally idle and cannot be reused.  These features make
 * this an ideal way to stop I/O in a disconnect() callback.
 * If the request has not already finished or been unlinked
 * the completion handler will see urb->status == -ENOENT.
 *
 * After and while the routine runs, attempts to resubmit the URB will fail
 * with error -EPERM.  Thus even if the URB's completion handler always
 * tries to resubmit, it will not succeed and the URB will become idle.
 *
 * The URB must not be deallocated while this routine is running.  In
 * particular, when a driver calls this routine, it must insure that the
 * completion handler cannot deallocate the URB.
 *
 * This routine may not be used in an interrupt context (such as a bottom
 * half or a completion handler), or when holding a spinlock, or in other
 * situations where the caller can't schedule().
 *
 * This routine should not be called by a driver after its disconnect
 * method has returned.
 */
void usb_poison_urb(struct urb *urb)
{
	might_sleep();
	if (!urb)
		return;
	atomic_inc(&urb->reject);
	/*
	 * Order the write of urb->reject above before the read
	 * of urb->use_count below.  Pairs with the barriers in
	 * __usb_hcd_giveback_urb() and usb_hcd_submit_urb().
	 */
	smp_mb__after_atomic();

	if (!urb->dev || !urb->ep)
		return;

	usb_hcd_unlink_urb(urb, -ENOENT);
	wait_event(usb_kill_urb_queue, atomic_read(&urb->use_count) == 0);
}
EXPORT_SYMBOL_GPL(usb_poison_urb);

void usb_unpoison_urb(struct urb *urb)
{
	if (!urb)
		return;

	atomic_dec(&urb->reject);
}
EXPORT_SYMBOL_GPL(usb_unpoison_urb);

int usb_hcd_submit_urb (struct urb *urb, gfp_t mem_flags)
{
	int			status;
	struct usb_hcd		*hcd = bus_to_hcd(urb->dev->bus);

	/* increment urb's reference count as part of giving it to the HCD
	 * (which will control it).  HCD guarantees that it either returns
	 * an error or calls giveback(), but not both.
	 */
	usb_get_urb(urb);
	atomic_inc(&urb->use_count);
	atomic_inc(&urb->dev->urbnum);
	usbmon_urb_submit(&hcd->self, urb);

	/* NOTE requirements on root-hub callers (usbfs and the hub
	 * driver, for now):  URBs' urb->transfer_buffer must be
	 * valid and usb_buffer_{sync,unmap}() not be needed, since
	 * they could clobber root hub response data.  Also, control
	 * URBs must be submitted in process context with interrupts
	 * enabled.
	 */

	if (is_root_hub(urb->dev)) {
		status = rh_urb_enqueue(hcd, urb, mem_flags);
	} else {
		status = map_urb_for_dma(hcd, urb, mem_flags);
		if (likely(status == 0)) {
			status = hcd->driver->urb_enqueue(hcd, urb, mem_flags);
			if (unlikely(status))
				unmap_urb_for_dma(hcd, urb);
		}
	}

	if (unlikely(status)) {
		usbmon_urb_submit_error(&hcd->self, urb, status);
		urb->hcpriv = NULL;
		INIT_LIST_HEAD(&urb->urb_list);
		atomic_dec(&urb->use_count);
		/*
		 * Order the write of urb->use_count above before the read
		 * of urb->reject below.  Pairs with the memory barriers in
		 * usb_kill_urb() and usb_poison_urb().
		 */
		smp_mb__after_atomic();

		atomic_dec(&urb->dev->urbnum);
		if (atomic_read(&urb->reject))
			wake_up(&usb_kill_urb_queue);
		usb_put_urb(urb);
	}
	return status;

static void __usb_hcd_giveback_urb(struct urb *urb)
{
	struct usb_hcd *hcd = bus_to_hcd(urb->dev->bus);
	struct usb_anchor *anchor = urb->anchor;
	int status = urb->unlinked;

	urb->hcpriv = NULL;
	if (unlikely((urb->transfer_flags & URB_SHORT_NOT_OK) &&
	    urb->actual_length < urb->transfer_buffer_length &&
	    !status))
		status = -EREMOTEIO;

	unmap_urb_for_dma(hcd, urb);
	usbmon_urb_complete(&hcd->self, urb, status);
	usb_anchor_suspend_wakeups(anchor);
	usb_unanchor_urb(urb);
	if (likely(status == 0))
		usb_led_activity(USB_LED_EVENT_HOST);

	/* pass ownership to the completion handler */
	urb->status = status;
	/*
	 * This function can be called in task context inside another remote
	 * coverage collection section, but kcov doesn't support that kind of
	 * recursion yet. Only collect coverage in softirq context for now.
	 */
	kcov_remote_start_usb_softirq((u64)urb->dev->bus->busnum);
	urb->complete(urb);
	kcov_remote_stop_softirq();

	usb_anchor_resume_wakeups(anchor);
	atomic_dec(&urb->use_count);
	/*
	 * Order the write of urb->use_count above before the read
	 * of urb->reject below.  Pairs with the memory barriers in
	 * usb_kill_urb() and usb_poison_urb().
	 */
	smp_mb__after_atomic();

void proc_entry_rundown(struct proc_dir_entry *de)
{
	DECLARE_COMPLETION_ONSTACK(c);
	/* Wait until all existing callers into module are done. */
	de->pde_unload_completion = &c;
	if (atomic_add_return(BIAS, &de->in_use) != BIAS)
		wait_for_completion(&c);

	/* ->pde_openers list can't grow from now on. */

	spin_lock(&de->pde_unload_lock);
	while (!list_empty(&de->pde_openers)) {
		struct pde_opener *pdeo;
		pdeo = list_first_entry(&de->pde_openers, struct pde_opener, lh);
		close_pdeo(de, pdeo);
		spin_lock(&de->pde_unload_lock);
	}
	spin_unlock(&de->pde_unload_lock);
}

struct hgic_usb_buf {
    struct list_head  list;
    struct hgic_usb  *usbdev;
    struct urb       *urb;
    void             *data;
    int               flag;
};

struct hgic_usb {
    struct usb_device *udev;
    uint   ep_in, ep_out;
    uint   ep_out_size, ep_in_size;
    uint   status;
    struct list_head  tx_freeq;
    struct list_head  rx_freeq;
    struct list_head  used;
    struct semaphore  tx_sema;
    spinlock_t qlock;
    struct hgic_bus bus;
};

static int txq_cnt = HGIC_TX_URB_CNT;
static int rxq_cnt = HGIC_RX_URB_CNT;
static hgic_probe probe_hdl = NULL;
static u32 max_pkt_len = HGIC_PKT_MAX_LEN;

static const struct usb_device_id hgic_usb_wdev_ids[] = {
    { USB_DEVICE(HGIC_VENDOR_ID, HGIC_WLAN_8400)},
    { /* end: all zeroes */             },
};
MODULE_DEVICE_TABLE(usb, hgic_usb_wdev_ids);
static void hgic_usb_receive(struct urb *urb);

static void hgic_usb_cancle(struct hgic_usb *usbdev)
{
    unsigned long flags;
    struct hgic_usb_buf *buf, *n;

    spin_lock_irqsave(&usbdev->qlock, flags);
    list_for_each_entry_safe(buf, n, &usbdev->used, list) {
        usb_unlink_urb(buf->urb);
    }
    spin_unlock_irqrestore(&usbdev->qlock, flags);
}

static void hgic_usb_quiesce(struct hgic_usb *usbdev)
{
    unsigned long flags;
    struct hgic_usb_buf *buf;

    /* Stop resubmission and synchronously drain callbacks OUTSIDE qlock:
     * usb_kill_urb may sleep and callbacks acquire this same spinlock.
     */
    usbdev->status |= HGIC_USB_STATUS_STOP;
    for (;;) {
        struct urb *urb;
        spin_lock_irqsave(&usbdev->qlock, flags);
        if (list_empty(&usbdev->used)) {
            spin_unlock_irqrestore(&usbdev->qlock, flags);
            break;
        }
        buf = list_first_entry(&usbdev->used, struct hgic_usb_buf, list);
        urb = usb_get_urb(buf->urb);
        spin_unlock_irqrestore(&usbdev->qlock, flags);
        usb_kill_urb(urb);
        usb_free_urb(urb);
    }
}
static void hgic_usb_free(struct hgic_usb *usbdev)
{
    unsigned long flags;
    struct hgic_usb_buf *buf, *n;

    hgic_usb_quiesce(usbdev);
    spin_lock_irqsave(&usbdev->qlock, flags);
    list_for_each_entry_safe(buf, n, &usbdev->tx_freeq, list) {
        list_del(&buf->list);
        usb_free_urb(buf->urb);
        if(buf->data){
            hgic_err("skb is not free??\r\n");
            kfree_skb(buf->data);
            buf->data = NULL;
        }
        kfree(buf);
    }
    list_for_each_entry_safe(buf, n, &usbdev->rx_freeq, list) {
        list_del(&buf->list);
        kfree(buf->data);
        usb_free_urb(buf->urb);
        kfree(buf);
    }
    WARN_ON(!list_empty(&usbdev->used));
    spin_unlock_irqrestore(&usbdev->qlock, flags);
}

static int hgic_usb_qinit(struct hgic_usb *usb, struct list_head *q, int qsize, u8 rx)
{
    int i = 0;
    struct hgic_usb_buf *buf = NULL;

    for (i = 0; i < qsize; i++) {
        buf = kzalloc(sizeof(struct hgic_usb_buf), GFP_ATOMIC);
        if (buf == NULL) {
            hgic_err("alloc fail, i=%d\r\n", i);
            break;
        }

        buf->usbdev = usb;
        buf->urb = usb_alloc_urb(0, GFP_KERNEL);
        if (buf->urb) {
            if (rx) {
                buf->data = kmalloc(max_pkt_len, GFP_KERNEL);
                if (buf->data == NULL) {
                    kfree(buf);
                    hgic_err("alloc fail, len=%d\r\n", max_pkt_len);
                    break;
                }
                buf->flag |= HGIC_USB_BUF_FLAG_RX;
            }
            list_add_tail(&buf->list, q);
        } else {
            kfree(buf);
            break;
        }
    }
    return i;

static void hgic_usb_tx_complete(struct urb *urb)
{
    struct hgic_usb_buf *buf = (struct hgic_usb_buf *)urb->context;
    struct hgic_usb     *usbdev = buf->usbdev;

    if (urb->status)
        hgic_attach_error(urb->status, HGIC_ATTACH_TX_COMPLETE);
    usbdev->bus.tx_complete(usbdev->bus.bus_priv, (struct sk_buff *)buf->data, !urb->status);
    buf->data = NULL;
    hgic_usb_enq(buf, &usbdev->tx_freeq);
    up(&usbdev->tx_sema);
}

static int hgic_usb_tx_packet(void *bus, struct sk_buff *skb)
{
    int ret = 0;
    int len = ALIGN(skb->len, 4);
    struct hgic_usb_buf *buf    = NULL;
    struct hgic_usb     *usbdev = container_of(bus, struct hgic_usb, bus);
    struct hgic_hdr *hdr = (struct hgic_hdr *)skb->data;
    bool token = false;

    /* P2 actual transport boundary: only the one init-owned command may pass.
     * This is not P3's atomic error/deadline versus submission fence.
     */
    if (!usbdev->bus.attach_tx_admit || !usbdev->bus.bus_priv) {
        ret = -EPERM;
        goto __fail;
    }
    ret = usbdev->bus.attach_tx_admit(usbdev->bus.bus_priv, skb);
    if (ret)
        goto __fail;
    if (!usbdev->ep_out_size) {
        ret = -EPROTO;
        goto __fail;
    }

    if (skb_is_nonlinear(skb) && skb_linearize(skb)) {
        ret = -ENOMEM;
        goto __fail;
    }
    hdr = (struct hgic_hdr *)skb->data;

    /* Stock retail REA0x1b3c8 unconditionally appends four transport bytes
     * at the endpoint packet boundary, not just URB_ZERO_PACKET. Keep the
     * protocol hdr.length at its original value and zero only wire padding.
     */
    if (IS_ALIGNED(len, usbdev->ep_out_size))
        len += 4;

    /* Object admission above already requires exact CMD/FWINFO. Never permit
     * CMD2 TX, data, credit, BT, maintenance or even BOOT ENTER here.
     */
    if (skb->len != sizeof(struct hgic_ctrl_hdr) || hdr->type != HGIC_HDR_TYPE_CMD) {
        ret = -EPERM;
        goto __fail;
    }
    if (len > skb->len) {
        int padding = len - skb->len;
        if (skb_tailroom(skb) < padding &&
            pskb_expand_head(skb, 0, padding, GFP_ATOMIC)) {
            ret = -ENOMEM;
            goto __fail;
        }
        skb_put_zero(skb, padding);
    }


    if ((usbdev->status & (HGIC_USB_STATUS_STOP | HGIC_USB_STATUS_ERR)) ||
        hgic_attach_failed()) {
        ret = -EIO;
        goto __fail;
    }

    ret = down_timeout(&usbdev->tx_sema, 1000);
    if (ret) {
        goto __fail;
    }
    token = true;

    if ((usbdev->status & (HGIC_USB_STATUS_STOP | HGIC_USB_STATUS_ERR)) ||
        hgic_attach_failed()) {
        ret = -EIO;
        goto __fail;
    }

    buf = hgic_usb_deq(usbdev, &usbdev->tx_freeq);
    if (buf == NULL) {
        ret = -ENOMEM;
        goto __fail;
    }
    buf->data = skb;
    usb_fill_bulk_urb(buf->urb, usbdev->udev, usb_sndbulkpipe(usbdev->udev, usbdev->ep_out),
                      skb->data, len, hgic_usb_tx_complete, buf);
    buf->urb->transfer_flags |= URB_ZERO_PACKET;
    ret = usb_submit_urb(buf->urb, GFP_ATOMIC);
    if (ret) {
        hgic_attach_error(ret, HGIC_ATTACH_TX_SUBMIT);
        hgic_err("usb_submit_urb failed, ret:%d\n", ret);
        goto __fail;
    }

    return ret;

__fail:
    hgic_attach_error(ret, HGIC_ATTACH_TX_SUBMIT);
    if (buf) {
        buf->data = NULL;
        hgic_usb_enq(buf, &usbdev->tx_freeq);
    }
    if (token)
        up(&usbdev->tx_sema);
    usbdev->bus.tx_complete(usbdev->bus.bus_priv, skb, 0);
    return ret;

__failed:
    hgic_attach_error(ret, HGIC_ATTACH_PROBE);
    if (published)
        usb_set_intfdata(intf, NULL);
    hgic_usb_quiesce(usbdev);
    if (usbdev->bus.remove) {
        usbdev->bus.remove(usbdev->bus.bus_priv);
    }
    hgic_usb_free(usbdev);
    if (device_ref)
        usb_put_dev(udev);
    kfree(usbdev);
    return ret;
}

static void hgic_usb_disconnect(struct usb_interface *intf)
{
    struct hgic_usb *usbdev = usb_get_intfdata(intf);
    hgic_dbg("Enter\n");
    if (usbdev) {
        usbdev->status |= HGIC_USB_STATUS_STOP;
        up(&usbdev->tx_sema);
        /* TX callbacks still reference bus_priv. Drain them before the
         * mac80211 core tears that object down, not after free_hw().
         */
        hgic_usb_quiesce(usbdev);
        if (usbdev->bus.remove) {
            usbdev->bus.remove(usbdev->bus.bus_priv);
        }
        hgic_usb_free(usbdev);
        usb_put_dev(usbdev->udev);
        kfree(usbdev);
        usb_set_intfdata(intf, NULL);
    }

static void attach_tx_work(struct work_struct *work)
{
    struct hgics_wdev *hg = container_of(work, struct hgics_wdev, tx_work);
    struct sk_buff *skb;
    /* One command only. No credit query, poll, sleep, retry or data loop. */
    skb = skb_dequeue(&hg->ctrl.txq);
    if (skb) {
        if (test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed())
            dev_kfree_skb_any(skb);
        else
            hg->bus->tx_packet(hg->bus, skb);
    }
    if (!skb_queue_empty(&hg->ctrl.txq))
        hgic_attach_error(-EPERM, HGIC_ATTACH_TX_ADMIT);
}

static void attach_schedule(struct hgic_fwctrl *ctrl)
{
    struct hgics_wdev *hg = container_of(ctrl, struct hgics_wdev, ctrl);
    if (!hg->tx_wq || test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed()) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return;
    }
    queue_work(hg->tx_wq, &hg->tx_work);
}

static void attach_probe_post(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned long flags;
    bool schedule = false;
    spin_lock_irqsave(&attach_lock, flags);
    if (!attach_receipt.first_error && !attach_receipt.init_queued &&
        attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED) {
        attach_receipt.init_queued = 1;
        schedule = true;
    } else {
        attach_error_locked(attach_receipt.first_error ? attach_receipt.first_error : -EALREADY,
                            HGIC_ATTACH_INIT);
    }
    spin_unlock_irqrestore(&attach_lock, flags);
    if (schedule && !schedule_work(&hg->delay_init))
        hgic_attach_error(-EALREADY, HGIC_ATTACH_INIT);
}

static void attach_core_remove(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned int i;
    unsigned long flags;
    if (!hg)
        return;
    set_bit(HGICS_STATE_REMOVE, &hg->state);
    clear_bit(HGICS_STATE_START, &hg->state);
    spin_lock_irqsave(&attach_lock, flags);
    /* Identifies expected core-removal notifications only; not P4 retirement. */
    attach_receipt.netdev_teardown = 1;
    if (attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED ||
        attach_receipt.init_state == HGIC_ATTACH_RUNNING)
        attach_error_locked(-ECANCELED, HGIC_ATTACH_INIT);
    spin_unlock_irqrestore(&attach_lock, flags);
    if (hg->primitives_ready) {
        cancel_work_sync(&hg->delay_init);
        cancel_work_sync(&hg->detect_work);
        cancel_work_sync(&hg->test_work);
        del_timer_sync(&hg->detect_tmr);
        del_timer_sync(&hg->beacon_timer);
        cancel_work_sync(&hg->tx_work);
    }
    if (hg->hw_registered)
        ieee80211_unregister_hw(hg->hw); /* DOWN: no successful start/interface */
    if (hg->ctrl_ready)
        hgic_fwctrl_release(&hg->ctrl);
    if (hg->tx_wq)
        destroy_workqueue(hg->tx_wq);
    if (hg->hw_initialized)
        hg->hghw->ops->free(hg);
    if (hg->primitives_ready) {
        for (i = 0; i < IEEE80211_NUM_ACS; i++)
            hgic_clear_queue(&hg->data_txq[i]);
        hgic_clear_queue(&hg->trans_q);
        hgic_clear_queue(&hg->ack_q);
        hgic_clear_queue(&hg->evt_list);
    }
    /* P2 guards initialization stages, NOT P4 submitter/URB/ref retirement. */
    WRITE_ONCE(attach_wiphy, NULL);
    ieee80211_free_hw(hg->hw);
